#include <stdio.h>
int global_operations[120];
void emit(char *tag,int *a,int extent,int i,int j) { int k; printf("%s %d %d",tag,i,j); for(k=0;k<extent;++k) printf(" %d",a[k]); printf("\n"); }
void operations_write_update(int i,int n,int m) { int a[120],j=99,k,repeat; for(k=0;k<120;++k) a[k]=-999; for(;i<n;++i) { for(j=0;j<m;++j) { a[i*10+j]=(i*37+j+7); a[i*10+j]=a[i*10+j]+(i*11+j+19); } } emit("write_update",a,120,i,j); }
void operations_update_write(int i,int n,int m) { int a[120],j=99,k,repeat; for(k=0;k<120;++k) a[k]=-999; for(;i<n;++i) { for(j=0;j<m;++j) { a[i*10+j]=a[i*10+j]+(i*37+j+7); a[i*10+j]=(i*11+j+19); } } emit("update_write",a,120,i,j); }
void operations_updates(int i,int n,int m) { int a[120],j=99,k,repeat; for(k=0;k<120;++k) a[k]=-999; for(;i<n;++i) { for(j=0;j<m;++j) { a[i*10+j]=a[i*10+j]+(i*37+j+7); a[i*10+j]=a[i*10+j]+(i*11+j+19); a[i*10+j]=a[i*10+j]+(i*23+j+3); } } emit("updates",a,120,i,j); }
void operations_row_mixed(int i,int n,int m) { int a[120],j=99,k,repeat; for(k=0;k<120;++k) a[k]=-999; for(;i<n;++i) { for(j=0;j<m;++j) { a[i*10+j]=(i*37+j+7); a[i*10+j]=a[i*10]+(i*11+j+19); a[i*10+j]=a[i*10+j]+(i*23+j+3); } } emit("row_mixed",a,120,i,j); }
void operations_duplicate_update(int i,int n,int m) { int a[120],j=99,k,repeat; for(k=0;k<120;++k) a[k]=-999; for(;i<n;++i) { for(j=0;j<m;++j) { a[i*10+j]=a[i*10+j]+(i*37+j+7); a[i*10+j]=a[i*10+j]+(i*37+j+7); a[i*10+j]=(i*11+j+19); a[i*10+j]=a[i*10+j]+(i*23+j+3); } } emit("duplicate_update",a,120,i,j); }
void operations_goto(int i,int n,int m) { int a[120],j=99,k,repeat; for(k=0;k<120;++k) a[k]=-999; goto work; work: for(;i<n;++i) { for(j=0;j<m;++j) { a[i*10+j]=(i*37+j+7); a[i*10+j]=a[i*10+j]+(i*11+j+19); } } emit("goto",a,120,i,j); }
void operations_global(int i,int n,int m) { int j=99,k,repeat; for(k=0;k<120;++k) global_operations[k]=-999; for(;i<n;++i) { for(j=0;j<m;++j) { global_operations[i*10+j]=(i*37+j+7); global_operations[i*10+j]=global_operations[i*10+j]+(i*11+j+19); } } emit("global",global_operations,120,i,j); }
void operations_enclosing(int i,int n,int m) { int a[120],j=99,k,repeat; for(k=0;k<120;++k) a[k]=-999; for(repeat=0;repeat<2;++repeat) { i=0; for(;i<n;++i) { for(j=0;j<m;++j) { a[i*10+j]=(i*37+j+7); a[i*10+j]=a[i*10+j]+(i*11+j+19); } } } emit("enclosing",a,120,i,j); }
int operations_unread_bound(int i,int n) { int a[120],j=99,m; for(;i<n;++i) { for(j=0;j<m;++j) { a[i*10+j]=(i*37+j+7); a[i*10+j]=a[i*10+j]+(i*11+j+19); } } return j; }
void operations_other_layout(int i,int n,int m) { int a[105],j=99,k,repeat; for(k=0;k<105;++k) a[k]=-999; for(;i<n;++i) { for(j=0;j<m;++j) { a[i*7+j]=(i*37+j+7); a[i*7+j]=a[i*7]+(i*11+j+19); a[i*7+j]=a[i*7+j]+(i*23+j+3); } } emit("other_layout",a,105,i,j); }
void operations_neighbor(int n,int m) { int a[120],i=0,j=99,k; for(k=0;k<120;++k) a[k]=-999; for(;i<n;++i) { for(j=0;j<m;++j) { a[i*10+j]=i*37+j+7; a[i*10+j]=a[i*10+j+1]+(i*11+j+19); }} emit("neighbor",a,120,i,j); }
void operations_two_arrays(int n,int m) { int a[120],b[120],i=0,j=99,k; for(k=0;k<120;++k) {a[k]=-999; b[k]=-999;} for(;i<n;++i) {for(j=0;j<m;++j) {a[i*10+j]=i*37+j+7; b[i*10+j]=a[i*10+j]+(i*11+j+19);}} emit("array-a",a,120,i,j);emit("array-b",b,120,i,j); }
int main(void) {int n,m; for(n=0;n<=12;++n) { for(m=0;m<=10;++m) { operations_write_update(0,n,m); operations_update_write(0,n,m); operations_updates(0,n,m); operations_row_mixed(0,n,m); operations_duplicate_update(0,n,m); operations_goto(0,n,m); operations_global(0,n,m); operations_enclosing(0,n,m); operations_write_update(2,n,m); operations_row_mixed(2,n,m); }} for(n=0;n<=15;++n) {for(m=0;m<=7;++m) operations_other_layout(0,n,m);} operations_write_update(0,-1,10); operations_row_mixed(0,5,-1); operations_neighbor(10,9); operations_two_arrays(12,10); printf("unread %d %d\n",operations_unread_bound(0,0),operations_unread_bound(2,1)); return 0;}
